import {uid,clone,I,point,inverse,mul,translate,splitSegment} from './core.js';
export const reflection=axis=>[-1,0,0,1,axis*2,0];
export function identifyNodes(o){o.nodes?.forEach(n=>n.nid??=uid());}
export function mirrorPoint(p,axis){return {x:2*axis-p.x,y:p.y};}
export function geometryMirror(o,axis=350){identifyNodes(o);const pairs={};const used=new Set();for(const n of o.nodes){if(used.has(n.nid))continue;const p=point(o.matrix,n),wanted=mirrorPoint(p,axis);let best,dist=Infinity;for(const q of o.nodes){if(used.has(q.nid))continue;const w=point(o.matrix,q),d=Math.hypot(w.x-wanted.x,w.y-wanted.y);if(d<dist){dist=d;best=q;}}if(best&&dist<Math.max(3,Math.abs(p.x-axis)*.12)){pairs[n.nid]=best.nid;pairs[best.nid]=n.nid;used.add(n.nid);used.add(best.nid);}}
o.symmetry={axis,pairs};return o.symmetry;}
export function syncNode(o,index,side,axis=o.symmetry?.axis??350){if(!o.symmetry)return;identifyNodes(o);const n=o.nodes[index],partner=o.nodes.find(p=>p.nid===o.symmetry.pairs[n.nid]);if(!partner)return;const inv=inverse(o.matrix),mirror=p=>point(inv,mirrorPoint(point(o.matrix,p),axis));if(n===partner){const w=point(o.matrix,n);Object.assign(n,point(inv,{x:axis,y:w.y}));if(side&&n[side])n[side==='in'?'out':'in']=mirror(n[side]);return;}if(!side){const q=mirror(n);partner.x=q.x;partner.y=q.y;if(n.kind)partner.kind=n.kind;else delete partner.kind;for(const [a,b]of[['in','out'],['out','in']]){if(n[a])partner[b]=mirror(n[a]);else delete partner[b];}}else {const opposite=side==='in'?'out':'in';partner[opposite]=mirror(n[side]);if(n.kind==='symmetric'||n.kind==='smooth'){const other=side==='in'?'out':'in';if(n[other])partner[side]=mirror(n[other]);}}}
export function addSymmetricNode(o,index,t=.5,live=true){identifyNodes(o);if(!live||!o.symmetry)return splitSegment(o,index,t);const a=o.nodes[index],b=o.nodes[(index+1)%o.nodes.length],pa=o.symmetry.pairs[a.nid],pb=o.symmetry.pairs[b.nid];const newIndex=splitSegment(o,index,t);identifyNodes(o);const first=o.nodes[newIndex];if(pa===b.nid&&pb===a.nid){if(Math.abs(t-.5)<.0001){o.symmetry.pairs[first.nid]=first.nid;syncNode(o,newIndex);return newIndex;}const segment=t<.5?index+1:index,normalized=t<.5?(1-2*t)/(1-t):(1-t)/t;const secondIndex=splitSegment(o,segment,normalized);identifyNodes(o);const second=o.nodes[secondIndex];o.symmetry.pairs[first.nid]=second.nid;o.symmetry.pairs[second.nid]=first.nid;return o.nodes.findIndex(n=>n.nid===first.nid);}const mateIndex=o.nodes.findIndex((n,i)=>n.nid===pb&&o.nodes[(i+1)%o.nodes.length]?.nid===pa);if(mateIndex>=0&&mateIndex!==index&&mateIndex!==newIndex){const j=splitSegment(o,mateIndex,1-t);identifyNodes(o);const second=o.nodes[j];o.symmetry.pairs[first.nid]=second.nid;o.symmetry.pairs[second.nid]=first.nid;return o.nodes.findIndex(n=>n.nid===first.nid);}geometryMirror(o,o.symmetry.axis);return newIndex;}
export function deleteSymmetricNode(o,index,live=true){identifyNodes(o);const n=o.nodes[index];if(!n)return false;const mate=live?o.symmetry?.pairs[n.nid]:null;const remove=new Set([n.nid,mate].filter(Boolean));if(o.nodes.length-remove.size<(o.closed?3:2))return false;o.nodes=o.nodes.filter(n=>!remove.has(n.nid));if(o.symmetry)for(const id of remove){delete o.symmetry.pairs[id];}return true;}
export function pairObjects(a,b,axis=350){a.mirrorPeer=b.id;b.mirrorPeer=a.id;initializePairGeometry(a,b,axis);}
function initializePairGeometry(a,b,axis){b.matrix=mul(reflection(axis),a.matrix);if(a.collapseBackup)b.collapseBackup=mul(reflection(axis),a.collapseBackup);else delete b.collapseBackup;if(a.nodes){b.nodes=clone(a.nodes);b.closed=a.closed;b.subpaths=clone(a.subpaths||[]);if(a.semanticEdges)b.semanticEdges=clone(a.semanticEdges);}b.modifiers=clone(a.modifiers||[]);b.fill=a.fill;b.stroke=a.stroke;b.width=a.width;b.opacity=a.opacity;for(const key of ['src','text','w','h','fontSize'])if(a[key]!==undefined)b[key]=clone(a[key]);if(a.pocket)b.pocket=clone(a.pocket);if(a.component)b.component=clone(a.component);}
export function breakSymmetry(objects,ids){for(const o of objects.filter(o=>ids.includes(o.id))){delete o.symmetry;if(o.mirrorPeer){const peer=objects.find(p=>p.id===o.mirrorPeer);if(peer)delete peer.mirrorPeer;delete o.mirrorPeer;}}}
export function setupTemplateSymmetry(p){p.schemaVersion=2;p.centerAxis=350;p.liveMirror=true;p.showAxis=true;for(const os of Object.values(p.views)){for(const o of os){if(o.role==='body')geometryMirror(o,350);}for(const left of os.filter(o=>/izquierd/.test(o.name))){const right=os.find(o=>o.name===left.name.replace('izquierda','derecha').replace('izquierdo','derecho'));if(right)pairObjects(left,right,350);}}return p;}
